$_MODULE['<{fondouk}prestashop>fondouk_8e8181764af2fa55804d41cf0a654f65'] = 'يجلب عدة منتجات حسب المعرّفات في نداء واحد (دفعة). استخدمه عندما تكون لديك بالفعل معرّفات المنتجات/المتغيّرات وتريد سعرها/توفّرها الحالي. 100 معرّف كحدّ أقصى. للقراءة فقط.';
$_MODULE['<{fondouk}prestashop>fondouk_525441b1671383fb5ca4a97290859d15'] = 'يجلب التفاصيل الكاملة لمنتج واحد حسب معرّفه (المُحصَّل عليه عبر search_catalog أو lookup_catalog). استخدمه عندما يريد الزبون تفاصيل منتج معيّن أو متغيّراته أو توفّره. يُرجع خطأ "not_found" واضحًا إذا لم يطابق المعرّف أي منتج عام. للقراءة فقط.';
$_MODULE['<{fondouk}prestashop>fondouk_c6473e3b01e34fd0b058e9a3ed91df7b'] = 'Fondouk — جاهز لوكلاء الذكاء الاصطناعي (UCP، MCP)';
