$_MODULE['<{fondouk}prestashop>diagnostic_fee367d016f8a36f1dd7829a97dac36b'] = 'كتالوج REST';
$_MODULE['<{fondouk}prestashop>fondouk_08897d3ed394643a7b915d173de95a51'] = 'يبحث عن المنتجات في الكتالوج العام للتاجر بنص حر وبمرشّحات اختيارية (الفئات، السعر). استخدمه عندما لا يكون لديك معرّف منتج — مثل «أحذية جري زرقاء بأقل من 100 €». يُرجع المنتجات مع الأسعار (شاملة الضريبة) والمتغيّرات والتوفّر. مقسّم إلى صفحات (مؤشّر). للقراءة فقط.';
