$_MODULE['<{fondouk}prestashop>fondouk_5cb680538055a390c0928ab3cbc7ee5d'] = 'وصلت طلبات الوكلاء إلى المتجر عبر وسيط (اتصال من %s مع ترويسة X-Forwarded-For)، لكن لم يُعلَن عن أي وسيط موثوق: يتشارك جميع الوكلاء خلفه حدًّا واحدًا لمعدل الطلبات.';
$_MODULE['<{fondouk}prestashop>fondouk_112d2a60864b797a0f9d1b05afeac327'] = 'في شاشة الوحدة، أعلن عن عناوين الوسطاء الذين تتحكم بهم (وكيل عكسي، موازن أحمال، شبكة توصيل محتوى)، ثم أعد تشغيل التشخيص.';
$_MODULE['<{fondouk}prestashop>fondouk_ca6e5bb22f30d12eeb75d2a676178460'] = 'لم يُعلَن عن أي وسيط موثوق ولم يُكتشف أي وسيط. الاكتشاف ليس شاملًا: إذا كان متجرك خلف وكيل عكسي أو شبكة توصيل محتوى، فأعلن عنه في شاشة الوحدة.';
$_MODULE['<{fondouk}prestashop>diagnostic_692cb0be3373db6c81d816936e308f78'] = 'الوسطاء الموثوق بهم (اختياري)';
$_MODULE['<{fondouk}prestashop>diagnostic_bbfd176a7e5b50fab00b0c558d2f4a73'] = 'فقط إذا كان متجرك خلف وكيل عكسي أو موازن أحمال أو شبكة توصيل محتوى تتحكم بها: أدرج عناوينها (عنوان IP أو نطاق CIDR، واحد في كل سطر). يستخدم حد معدل الطلبات حينئذ عنوان الزائر الذي تنقله. وإلا فاتركه فارغًا: لا يُوثق بالعناوين المنقولة افتراضيًا أبدًا.';
$_MODULE['<{fondouk}prestashop>diagnostic_5cb680538055a390c0928ab3cbc7ee5d'] = 'وصلت طلبات الوكلاء إلى المتجر عبر وسيط (اتصال من %s مع ترويسة X-Forwarded-For)، لكن لم يُعلَن عن أي وسيط موثوق: يتشارك جميع الوكلاء خلفه حدًّا واحدًا لمعدل الطلبات.';
